 @page "/board"
 @using sv_ccacbfd535b8460da7cfcb8e8468cc2c.Components.Pages.Board
 @rendermode InteractiveServer
 @inject ITaskService TaskService

 <PageTitle>Kanban Board</PageTitle>

 @if (isLoading)
 {
     <p class="loading-message">Loading tasks...</p>
 }
 else if (errorMessage is not null)
 {
     <p class="error-message">@errorMessage</p>
 }
 else
 {
     <BoardStatsBar Total="@allTasks.Count"
                    ToDo="@CountByStatus(StatusToDo)"
                    InProgress="@CountByStatus(StatusInProgress)"
                    DoneCount="@CountByStatus(StatusDone)"
                    Overdue="@allTasks.Count(t => t.DueDate < DateTime.Today)" />

     <BoardSearchBar SearchText="@searchText" SearchTextChanged="OnSearchChanged" />

     <div class="kanban-board">
         <KanbanColumn Title="To Do" Status="@StatusToDo"
                       Tasks="@GetFilteredTasks(StatusToDo)"
                       CanMoveLeft="false" CanMoveRight="true"
                       OnMoveTaskRight="@(id => MoveTask(id, StatusInProgress))"
                       OnAddTask="@(data => AddTask(data, StatusToDo))" />

         <KanbanColumn Title="In Progress" Status="@StatusInProgress"
                       Tasks="@GetFilteredTasks(StatusInProgress)"
                       CanMoveLeft="true" CanMoveRight="true"
                       OnMoveTaskLeft="@(id => MoveTask(id, StatusToDo))"
                       OnMoveTaskRight="@(id => MoveTask(id, StatusDone))"
                       OnAddTask="@(data => AddTask(data, StatusInProgress))" />

         <KanbanColumn Title="Done" Status="@StatusDone"
                       Tasks="@GetFilteredTasks(StatusDone)"
                       CanMoveLeft="true" CanMoveRight="false"
                       OnMoveTaskLeft="@(id => MoveTask(id, StatusInProgress))"
                       OnAddTask="@(data => AddTask(data, StatusDone))" />
     </div>
 }

 @code {
     private const string StatusToDo = "To Do";
     private const string StatusInProgress = "In Progress";
     private const string StatusDone = "Done";

     private List<TaskItem> allTasks = new();
     private string searchText = "";
     private bool isLoading = true;
     private string? errorMessage;

     protected override async Task OnInitializedAsync()
     {
         try
         {
             allTasks = await TaskService.GetAllTasksAsync();
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to load tasks: {ex.Message}";
         }
         finally
         {
             isLoading = false;
         }
     }

     private int CountByStatus(string status) =>
         allTasks.Count(t => t.Status == status);

     private List<TaskItem> GetFilteredTasks(string status) =>
         allTasks
             .Where(t => t.Status == status)
             .Where(t => string.IsNullOrWhiteSpace(searchText)
                 || t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase))
             .ToList();

     private void OnSearchChanged(string value) => searchText = value;

     private async Task MoveTask(int taskId, string newStatus)
     {
         try
         {
             await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
             var task = allTasks.FirstOrDefault(t => t.Id == taskId);
             if (task is not null)
             {
                 allTasks = allTasks.Select(t => t.Id == taskId
                     ? t with { Status = newStatus }
                     : t).ToList();
             }
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to move task: {ex.Message}";
         }
     }

     private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
     {
         try
         {
             var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
             allTasks.Add(newTask);
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to add task: {ex.Message}";
         }
     }
 }

